<?php

namespace App\Models;

use App\Jobs\SyncSwitchConfig;
use Illuminate\Database\Eloquent\Attributes\Fillable;
use Illuminate\Database\Eloquent\Attributes\Hidden;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Str;

/**
 * A PBX phone (SIP user) of a customer account. The SIP password and voicemail
 * PIN are encrypted with the app key, so FreeSWITCH's directory entry is
 * generated by App\Services\Freeswitch\PbxSync rather than read from the table.
 */
#[Hidden(['sip_password', 'voicemail_pin'])]
#[Fillable(['account_id', 'extension', 'name', 'sip_username', 'sip_password', 'caller_id_number', 'outbound_enabled',
    'voicemail_enabled', 'voicemail_pin', 'ring_seconds', 'enabled'])]
class PbxExtension extends Model
{
    protected function casts(): array
    {
        return [
            'sip_password' => 'encrypted',
            'voicemail_pin' => 'encrypted',
            'outbound_enabled' => 'boolean',
            'voicemail_enabled' => 'boolean',
            'ring_seconds' => 'integer',
            'enabled' => 'boolean',
        ];
    }

    public function account(): BelongsTo
    {
        return $this->belongsTo(Account::class);
    }

    /** A strong random SIP password (phones store it; nobody types it twice). */
    public static function generatePassword(): string
    {
        return Str::password(20, symbols: false);
    }

    /** Default SIP username: extension plus a slug of the account code, e.g. "1001.acme". */
    public static function suggestUsername(Account $account, string $extension): string
    {
        $slug = Str::of($account->code)->lower()->replaceMatches('/[^a-z0-9]+/', '')->limit(40, '')->value() ?: "a{$account->id}";

        return "{$extension}.{$slug}";
    }

    protected static function booted(): void
    {
        // FreeSWITCH's SIP directory follows the database.
        static::saved(fn () => SyncSwitchConfig::soon());
        static::deleted(fn () => SyncSwitchConfig::soon());
    }
}
